package com.checklist.domain.github.service;
import com.checklist.domain.github.dto.GithubDtos.*;
import com.checklist.domain.checklist.dto.ItemDtos;
import com.checklist.domain.checklist.service.ItemService;
import com.checklist.domain.github.service.GithubRepositoryValidator;
import com.checklist.global.api.ApiException;


import com.checklist.global.api.ApiException;import com.fasterxml.jackson.databind.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
import java.net.*;import java.net.http.*;import java.time.Duration;import java.util.*;

@org.springframework.stereotype.Service public class GithubService {
 private final ObjectMapper mapper;private final ItemService items;
 public GithubService(ObjectMapper m,ItemService i){mapper=m;items=i;}
 private record Remote(JsonNode data,String link){}
 public Page issues(Long user,Request r){if(r==null)throw ApiException.bad("INVALID_INPUT","요청 내용이 필요합니다.");GithubRepositoryValidator.validate(r.repository());int page=r.page()==null?1:r.page();if(page<1||page>1000)throw ApiException.bad("INVALID_PAGE","페이지 값이 올바르지 않습니다.");String state=r.state()==null?"open":r.state();if(!Set.of("open","closed","all").contains(state))throw ApiException.bad("INVALID_STATE","이슈 상태 값이 올바르지 않습니다.");try{Remote remote=get("https://api.github.com/repos/"+r.repository()+"/issues?state="+state+"&per_page=100&page="+page,r.token());List<Issue> list=new ArrayList<>();for(JsonNode n:remote.data()){if(n.has("pull_request"))continue;list.add(new Issue(n.path("number").asInt(),n.path("title").asText(),n.path("body").asText(""),n.path("html_url").asText(),n.path("state").asText()));}return new Page(list,remote.link().contains("rel=\"next\""),page);}catch(ApiException e){throw e;}catch(Exception e){throw new ApiException(org.springframework.http.HttpStatus.BAD_GATEWAY,"GITHUB_UNAVAILABLE","GitHub 이슈를 가져오지 못했습니다.");}}
 public Imported importIssues(Long actor,ImportRequest r){if(r==null)throw ApiException.bad("INVALID_INPUT","요청 내용이 필요합니다.");String repo=GithubRepositoryValidator.validate(r.repository());if(r.issueNumbers()==null||r.issueNumbers().isEmpty()||r.issueNumbers().size()>100||r.issueNumbers().stream().anyMatch(n->n==null||n<1))throw ApiException.bad("INVALID_SELECTION","1~100개의 유효한 이슈 번호를 선택해 주세요.");List<ItemDtos.Item> created=new ArrayList<>();List<Integer> skipped=new ArrayList<>();for(Integer n:new LinkedHashSet<>(r.issueNumbers())){try{if(items.existsByGithubRepositoryAndGithubIssueNumber(repo,n)){skipped.add(n);continue;}JsonNode i=get("https://api.github.com/repos/"+repo+"/issues/"+n,r.token()).data();if(i.has("pull_request")){skipped.add(n);continue;}ItemDtos.Item item=items.importIssue(actor,repo,n,i.path("title").asText(),i.path("body").asText(""),i.path("html_url").asText(),r.parentId());if(item==null)skipped.add(n);else created.add(item);}catch(ApiException e){throw e;}catch(Exception e){throw new ApiException(org.springframework.http.HttpStatus.BAD_GATEWAY,"GITHUB_UNAVAILABLE","GitHub 이슈를 가져오지 못했습니다.");}}return new Imported(created,skipped);}
 private Remote get(String address,String token)throws Exception{URI uri=URI.create(address);if(!"https".equals(uri.getScheme())||!"api.github.com".equalsIgnoreCase(uri.getHost())||uri.getUserInfo()!=null)throw ApiException.bad("INVALID_GITHUB_URL","GitHub 요청 주소가 올바르지 않습니다.");HttpRequest.Builder b=HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(15)).header("Accept","application/vnd.github+json").header("X-GitHub-Api-Version","2022-11-28").GET();if(token!=null&&!token.isBlank())b.header("Authorization","Bearer "+token);HttpClient c=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).followRedirects(HttpClient.Redirect.NEVER).build();HttpResponse<String> response=c.send(b.build(),HttpResponse.BodyHandlers.ofString());if(response.statusCode()<200||response.statusCode()>=300)throw new ApiException(org.springframework.http.HttpStatus.BAD_GATEWAY,"GITHUB_RESPONSE","GitHub 요청에 실패했습니다.");return new Remote(mapper.readTree(response.body()),response.headers().firstValue("Link").orElse(""));}
}
